#!/usr/bin/env bash
# Verifies Glance CLI behaviour the editor relies on (ADR-0009, ADR-0010, ADR-0011):
#   - config:print inlines $include files but keeps placeholders and comments literal
#   - config:print succeeds without the referenced env vars
#   - a leading "Generated by" comment passes config:validate
source "$(dirname "$0")/lib.sh"
guard_docker_host

work="$(mktemp -d)"; trap 'rm -rf "$work"' EXIT
failures=0
check() { if "$@"; then log "ok   $desc"; else log "BAD  $desc"; failures=$((failures + 1)); fi; }

{ echo "# Generated by Glance Editor. Do not edit."; cat "$REPO_ROOT/test/fixtures/valid/placeholders.yml"
  printf '  - $include: inc.yml\n'; } > "$work/glance.yml"
printf -- '- name: Included\n  columns:\n    - size: full\n      widgets:\n        - type: html\n          source: ${GLANCE_EDITOR_TEST_URL}\n' > "$work/inc.yml"
mapfile -t extra < <(placeholder_run_args)

desc="comment header + placeholders + include pass config:validate"
check glance_cli "$work" config:validate "${extra[@]}"

printed="$(glance_cli "$work" config:print 2>&1)"
has() { grep -qF -- "$1" <<<"$printed"; }
desc="config:print succeeds without env vars";             check test -n "$printed"
desc="config:print inlines \$include";                      check has "name: Included"
desc="config:print keeps \${VAR} literal";                  check has 'url: ${GLANCE_EDITOR_TEST_URL}'
desc="config:print keeps \${secret:…} literal";             check has '${secret:test_secret}'
desc="config:print keeps \${readFileFromEnv:…} literal";    check has '${readFileFromEnv:GLANCE_EDITOR_TEST_TOKEN_FILE}'
desc="config:print keeps \\\${…} escape literal";           check has '\${NOT_AN_ENV_VAR}'
desc="config:print keeps comments";                         check has "# Generated by Glance Editor"
desc="config:print leaves no \$include directive";          check bash -c '! grep -qF "\$include" <<<"$1"' _ "$printed"

# Placeholder edge cases (source: configVariablePattern in config.go v0.8.6). The editor's placeholder parser
# (packages/model/src/placeholder.ts) mirrors these; if Glance changes them, both must change.
edge="$work/edge"; mkdir -p "$edge"
base='pages:\n  - name: P\n    columns:\n      - size: full\n        widgets:\n          - type: html\n            source: '
# shellcheck disable=SC2059 # the argument is a format string on purpose (\n escapes)
validates() { printf "$1" > "$edge/glance.yml"; shift; glance_cli "$edge" config:validate "$@" >/dev/null 2>&1; }
rejects()   { ! validates "$@"; }
desc="placeholder: control, an unset \${VAR} fails validation";        check rejects "${base}x \${GE_UNSET}\n"
desc="placeholder: second of two adjacent placeholders is NOT substituted"; check validates "${base}x\${GE_SET}\${GE_UNSET}y\n" -e GE_SET=1
desc="placeholder: at column 0 of a later line is NOT substituted";       check validates "${base}ok\n\${GE_UNSET}: x\n"
desc="placeholder: lower-case name is left literal";                      check validates "${base}\${lower_case}\n"
desc="placeholder: unknown type is left literal";                         check validates "${base}\${foo:BAR}\n"
desc="placeholder: inside a comment IS substituted";                      check rejects "${base}ok\n# \${GE_UNSET}\n"

[[ $failures -eq 0 ]] || fail "$failures CLI check(s) failed"
log "all CLI checks passed"
